                    long res = 0;
                    for (Long v : vars) {
                        res += (smallerCount + v) % 998244353;
                    }
                    totalResult += res % 998244353;
                }
            }
        }
        System.out.println(convertToString.apply(totalResult % 1000000007));
    }
}
